fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
    let me = self.project();
    while me.buf.has_remaining() {
        let n = if Pin::new(&mut *me.writer).is_write_vectored() {
            // The `IoSlice`s borrow from `me.buf`, so their scope must
            // end before `me.buf.advance` is called below.
            let mut slices: [IoSlice<'_>; VECTORED_CHUNKS] =
                [IoSlice::new(&[]); VECTORED_CHUNKS];
            let nchunks = me.buf.chunks_vectored(&mut slices);
            ready!(Pin::new(&mut *me.writer).poll_write_vectored(cx, &slices[..nchunks])?)
        } else {
            ready!(Pin::new(&mut *me.writer).poll_write(cx, me.buf.chunk())?)
        };

        me.buf.advance(n);
        if n == 0 {
            return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
        }
    }

    Poll::Ready(Ok(()))
}

